-- composition of rule kernels outer_join_simplification x statistics_propagation (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT 20 AS c0, a1.c5 AS c1, 'A'::text AS c2, 1000::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) AS ka UNION ALL SELECT 2 AS k FROM (SELECT 0 AS c0 FROM (tl AS a1 JOIN (t1 AS a2 FULL JOIN v0 AS a3 ON (a2.c1 = a3.c0)) ON ((a1.c0 = a3.c0) AND TRUE))) AS kb) AS u;
